import ast
from pathlib import Path

EXEMPT_PATHS = {"app/auth.py"}
WRITE_HINT_SUBSTRINGS = (
    "create",
    "update",
    "delete",
    "sync",
    "importer",
    "cleanup",
    "billing",
    "notifier",
    "mailer",
    "tokens_repo",
    "audit_repo",
    "uploads",
)

def _residual_legacy_calls(root: Path) -> list[tuple[str, int]]:
    hits = []
    for p in sorted(root.rglob("*.py")):
        rel = p.relative_to(root).as_posix()
        if rel in EXEMPT_PATHS or "verify_submission" in rel or "migrate" in rel or "audit_migration" in rel:
            continue
        try:
            tree = ast.parse(p.read_text(encoding="utf-8"))
        except (SyntaxError, OSError, UnicodeDecodeError):
            continue
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            func = node.func
            if isinstance(func, ast.Name) and func.id == "legacy_auth":
                hits.append((rel, node.lineno))
            elif isinstance(func, ast.Attribute) and func.attr == "legacy_auth":
                hits.append((rel, node.lineno))
    return hits

def _new_auth_scope_args(root: Path) -> list[tuple[str, int, str]]:
    out = []
    for p in sorted(root.rglob("*.py")):
        rel = p.relative_to(root).as_posix()
        if rel in EXEMPT_PATHS or "verify_submission" in rel or "migrate" in rel or "audit_migration" in rel:
            continue
        try:
            tree = ast.parse(p.read_text(encoding="utf-8"))
        except (SyntaxError, OSError, UnicodeDecodeError):
            continue
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            func = node.func
            name = ""
            if isinstance(func, ast.Name):
                name = func.id
            elif isinstance(func, ast.Attribute):
                name = func.attr
            if name != "new_auth":
                continue
            scope_val = "<missing>"
            for kw in node.keywords:
                if kw.arg == "scope":
                    if isinstance(kw.value, ast.Constant) and isinstance(kw.value.value, str):
                        scope_val = kw.value.value
                    else:
                        scope_val = "<dynamic>"
            if len(node.args) >= 2 and scope_val == "<missing>":
                if isinstance(node.args[1], ast.Constant) and isinstance(
                    node.args[1].value, str
                ):
                    scope_val = node.args[1].value
                else:
                    scope_val = "<dynamic>"
            out.append((rel, node.lineno, scope_val))
    return out

root = Path(".")
residuals = _residual_legacy_calls(root)
print(f"Residual legacy calls count: {len(residuals)}")
for r in residuals:
    print(f"  Residual: {r}")

new_calls = _new_auth_scope_args(root)
print(f"New auth calls count: {len(new_calls)}")

scopes_in_write_modules = [
    (rel, lineno, scope) for rel, lineno, scope in new_calls
    if any(hint in rel for hint in WRITE_HINT_SUBSTRINGS)
]

scopes_in_read_modules = [
    (rel, lineno, scope) for rel, lineno, scope in new_calls
    if not any(hint in rel for hint in WRITE_HINT_SUBSTRINGS)
]

print(f"\nScopes in write modules (should all be 'write'):")
all_write_correct = True
for rel, lineno, scope in scopes_in_write_modules:
    if scope != "write":
        all_write_correct = False
        print(f"  ❌ {rel}:{lineno} has scope {scope}")
    else:
        print(f"  ✅ {rel}:{lineno} has scope {scope}")

print(f"\nScopes in read modules (should all be 'read'):")
all_read_correct = True
for rel, lineno, scope in scopes_in_read_modules:
    if scope != "read":
        all_read_correct = False
        print(f"  ❌ {rel}:{lineno} has scope {scope}")
    else:
        print(f"  ✅ {rel}:{lineno} has scope {scope}")

if len(residuals) == 0 and all_write_correct and all_read_correct:
    print("\n🎉 PERFECT SCORE EXPECTED!")
else:
    print("\n❌ Issues detected.")
